import { describe, expect, it } from 'vitest';
import { sseFrames } from './Solution';

/**
 * 期望值由 gen.py 里的同一套 SSE 模型算出后**直接写进断言**，
 * 不再手抄一遍 —— 上一批题出现过"用例名与实际值对不上"的漂移，单向修等于没修。
 */
describe('sseFrames：跨 chunk 的 SSE 增量解析', () => {
  it("基线：两个完整事件", () => {
    expect(sseFrames(["data:hello\n\ndata:world\n\n"])).toEqual(["hello", "world"]);
  });
  it("CRLF 被劈在两个 chunk 之间：不许留下尾的 \\r", () => {
    expect(sseFrames(["data:tok\r", "\n\r\n"])).toEqual(["tok"]);
  });
  it("注释心跳不产生事件", () => {
    expect(sseFrames([": keep-alive\n", "data:tok\n\n"])).toEqual(["tok"]);
  });
  it("只剥掉冒号后的一个空格", () => {
    expect(sseFrames(["data:  two-space-start\n\n"])).toEqual([" two-space-start"]);
  });
  it("同一事件里的多条 data 用换行拼接", () => {
    expect(sseFrames(["data:line1\ndata:line2\n\n"])).toEqual(["line1\nline2"]);
  });
  it("结尾没有空行收束的半截事件必须丢弃", () => {
    expect(sseFrames(["data:full\n\ndata:part"])).toEqual(["full"]);
  });
  it("只有 event 字段不构成事件", () => {
    expect(sseFrames(["event:done\nid:7\n\n"])).toEqual([]);
  });
  it("裸 data 行（没有冒号）派发空字符串", () => {
    expect(sseFrames(["data\n\ndata\n\n"])).toEqual(["", ""]);
  });
  it("单独的 \\r 也是行分隔符", () => {
    expect(sseFrames(["data:part1\rdata:part2\r\r"])).toEqual(["part1\npart2"]);
  });
  it("退化：没有任何 chunk", () => {
    expect(sseFrames([])).toEqual([]);
  });
  it("只有分隔符：零个事件", () => {
    expect(sseFrames(["\n\n\n"])).toEqual([]);
  });
  it("一个 token 被劈成两半：必须跨 chunk 拼接", () => {
    expect(sseFrames(["data:ab", "cd\n\n"])).toEqual(["abcd"]);
  });
  it("非法：chunks 为 null", () => {
    expect(() => sseFrames(null as unknown as string[])).toThrow("chunks must be an array");
  });
  it("非法：某个 chunk 为 null", () => {
    expect(() => sseFrames(["data:a\n\n", null] as unknown as string[])).toThrow("chunk must be a string");
  });
});

