function splitLines(text: string): string[] {
  const lines: string[] = [];
  let cur = '';
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === '\r') {
      lines.push(cur);
      cur = '';
      if (text[i + 1] === '\n') i++;      // CRLF 是一行结束，不是两行
      continue;
    }
    if (ch === '\n') {
      lines.push(cur);
      cur = '';
      continue;
    }
    cur += ch;
  }
  lines.push(cur);
  return lines;
}

export function sseFrames(chunks: string[]): string[] {
  if (chunks == null) throw new Error('chunks must be an array');
  let text = '';
  for (const chunk of chunks) {
    if (chunk == null) throw new Error('chunk must be a string');
    text += chunk;
  }

  const out: string[] = [];
  let data: string[] = [];
  let sawData = false;

  for (const line of splitLines(text)) {
    if (line === '') {                      // 空行 = 派发
      if (sawData) out.push(data.join('\n'));
      data = [];
      sawData = false;
      continue;
    }
    if (line.startsWith(':')) continue;     // 心跳注释

    const colon = line.indexOf(':');
    let field: string;
    let value: string;
    if (colon === -1) {
      field = line;                         // 裸字段名 ⇒ 值为空串
      value = '';
    } else {
      field = line.slice(0, colon);
      value = line[colon + 1] === ' ' ? line.slice(colon + 2) : line.slice(colon + 1);
    }
    if (field === 'data') {
      data.push(value);
      sawData = true;
    }
  }
  // 循环结束后剩下的 data 缓冲是**没有被空行收束的半截事件**，按规则丢弃
  return out;
}

